// O(n^2): about 4e10 steps for n = 2e5
long long slow(vector<int>& a) {
    long long c = 0;
    for (size_t i = 0; i < a.size(); i++)
        for (size_t j = i + 1; j < a.size(); j++)
            if (a[i] + a[j] == 0) c++;
    return c;
}
// O(n): hash map of values seen so far
long long fast(vector<int>& a) {
    unordered_map<int,int> seen;
    long long c = 0;
    for (int x : a) { c += seen[-x]; seen[x]++; }
    return c;
}
